import React, { useState, useEffect } from "react";
import axios from "axios";
import {
  FaPlusCircle,
  FaQuestionCircle,
  FaClipboardList
} from "react-icons/fa";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import AlertBox from "./AlertBox";
import "./theme.css";

function QuizTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [subjectCode, setSubjectCode] = useState("");
  const [alert, setAlert] = useState(null);

  const [form, setForm] = useState({
    question: "",
    option_a: "",
    option_b: "",
    option_c: "",
    option_d: "",
    correct_answer: ""
  });

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    const res = await axios.get("http://127.0.0.1:8000/courses");
    const myCourses = (res.data.courses || []).filter(
      (c) => String(c.teacher_id) === String(teacherId)
    );
    setCourses(myCourses);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!subjectCode) {
      setAlert({ message: "Select subject first", type: "error" });
      return;
    }

    try {
      const payload = { ...form, subject_code: subjectCode };

      const res = await axios.post(
        "http://127.0.0.1:8000/create-question",
        payload
      );

      setAlert({ message: res.data.message, type: "success" });

      setForm({
        question: "",
        option_a: "",
        option_b: "",
        option_c: "",
        option_d: "",
        correct_answer: ""
      });
    } catch (err) {
      console.error(err);
      setAlert({ message: "Failed to add question", type: "error" });
    }
  };

  return (
    <AppShell
      title="Quiz Creator"
      subtitle="Create MCQ-based quizzes for your subjects."
      action={<span className="badge badge-purple">Teacher Quiz Panel</span>}
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <Panel title="Create Question">
        <select
          className="select"
          onChange={(e) => setSubjectCode(e.target.value)}
        >
          <option value="">Select Subject</option>
          {courses.map((c) => (
            <option key={c.id} value={c.subject_code}>
              {c.title} ({c.subject_code})
            </option>
          ))}
        </select>

        <form onSubmit={handleSubmit}>
          <input
            className="input"
            placeholder="Question"
            value={form.question}
            onChange={(e) =>
              setForm({ ...form, question: e.target.value })
            }
          />

          <input className="input" placeholder="Option A"
            value={form.option_a}
            onChange={(e)=>setForm({...form,option_a:e.target.value})}/>

          <input className="input" placeholder="Option B"
            value={form.option_b}
            onChange={(e)=>setForm({...form,option_b:e.target.value})}/>

          <input className="input" placeholder="Option C"
            value={form.option_c}
            onChange={(e)=>setForm({...form,option_c:e.target.value})}/>

          <input className="input" placeholder="Option D"
            value={form.option_d}
            onChange={(e)=>setForm({...form,option_d:e.target.value})}/>

          <input
            className="input"
            placeholder="Correct Answer (A/B/C/D)"
            value={form.correct_answer}
            onChange={(e) =>
              setForm({ ...form, correct_answer: e.target.value })
            }
          />

          <button className="btn btn-primary">
            <FaPlusCircle /> Add Question
          </button>
        </form>
      </Panel>
    </AppShell>
  );
}

export default QuizTeacher;
